import{_ as t}from"./chunks/cngal-background-logo.CTvRSuWB.js";import{_ as o,o as e,c as r,a5 as i}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"Konado について","description":"","frontmatter":{"title":"Konado について","order":1},"headers":[],"relativePath":"ja/latest/introduction/konado.md","filePath":"ja/latest/introduction/konado.md","lastUpdated":1788455378000}'),s={name:"ja/latest/introduction/konado.md"};function n(d,a,h,l,c,p){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="konado-について" tabindex="-1">Konado について <a class="header-anchor" href="#konado-について" aria-label="Permalink to &quot;Konado について&quot;">​</a></h1><h2 id="プロジェクト概要" tabindex="-1">プロジェクト概要 <a class="header-anchor" href="#プロジェクト概要" aria-label="Permalink to &quot;プロジェクト概要&quot;">​</a></h2><p>Konado は Godot Engine をベースにした、オープンソースコミュニティ主導のビジュアルノベルエンジンフレームワークです。私たちは、開発者に効率的で扱いやすいビジュアルノベル開発体験を提供し、クリエイターが高品質なビジュアルノベル作品を素早く構築できるよう支援することを目指しています。より親しみやすく効率的なツールを追求し、ゲーム制作者が実装の細部に悩まされることなく、物語の表現とアートに集中できる環境を作ります。</p><h2 id="プロジェクトの受賞・掲載" tabindex="-1">プロジェクトの受賞・掲載 <a class="header-anchor" href="#プロジェクトの受賞・掲載" aria-label="Permalink to &quot;プロジェクトの受賞・掲載&quot;">​</a></h2><ul><li>Konado は Godot Engine 公式の <a href="https://github.com/godotengine/awesome-godot" target="_blank" rel="noreferrer">awesome-godot</a> プロジェクトの「Plugins and scripts」セクションに、推奨プラグインの一つとして掲載されています。</li><li>Konado は <a href="https://atomgit.com/GitCode/G-Star100" target="_blank" rel="noreferrer">2025 AtomGit Top 100 Open Source Projects</a> に選出され、<a href="https://gstar-landscape.gitcode.com/?item=%E9%9F%B3%E8%A7%86%E9%A2%91-%E5%9B%BE%E5%BD%A2-%E6%B8%B8%E6%88%8F-3d--%E6%B8%B8%E6%88%8F%E5%BC%95%E6%93%8E-unity-unreal-godot--konado" target="_blank" rel="noreferrer">AtomGit G-Star Landscape 3.0</a> のエコシステムマップにも収録されています。</li></ul><h2 id="プロジェクト貢献者" tabindex="-1">プロジェクト貢献者 <a class="header-anchor" href="#プロジェクト貢献者" aria-label="Permalink to &quot;プロジェクト貢献者&quot;">​</a></h2><p>以下の貢献者チャートは <a href="https://contrib.rocks" target="_blank" rel="noreferrer">contrib.rocks</a> によって生成され、プロジェクト貢献者の情報をリアルタイムに更新します。</p><picture><source media="(prefers-color-scheme: dark)" srcset="https://contrib.rocks/image?repo=godothub/konado&amp;theme=dark"><source media="(prefers-color-scheme: light)" srcset="https://contrib.rocks/image?repo=godothub/konado"><img alt="Contributors" src="https://contrib.rocks/image?repo=godothub/konado"></picture><h2 id="github-star-history" tabindex="-1">GitHub Star History <a class="header-anchor" href="#github-star-history" aria-label="Permalink to &quot;GitHub Star History&quot;">​</a></h2><picture><source media="(prefers-color-scheme: dark)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;theme=dark&amp;legend=top-left"><source media="(prefers-color-scheme: light)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"><img alt="Star History Chart" src="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"></picture><h2 id="atomgit-star-history" tabindex="-1">AtomGit Star History <a class="header-anchor" href="#atomgit-star-history" aria-label="Permalink to &quot;AtomGit Star History&quot;">​</a></h2><p><img src="https://atomgit.com/godothub/konado/starcharts.svg?variant=adaptive" alt="AtomGit Star History"></p><h2 id="スポンサー" tabindex="-1">スポンサー <a class="header-anchor" href="#スポンサー" aria-label="Permalink to &quot;スポンサー&quot;">​</a></h2><p>Konado プロジェクトを気に入ってくださり、私たちの活動を支援したい場合は、以下の方法でスポンサーとしてご支援いただけます。</p><ul><li><a href="https://afdian.com/item/52230b2860a011f083ef52540025c377" target="_blank" rel="noreferrer">Afdian</a></li></ul><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>Konado プロジェクトに関心がある方は、QQ チャンネル交流グループに参加し、Konado の今後の発展について一緒に議論してください。</p><ul><li>QQ チャンネル交流グループ：<a href="https://pd.qq.com/g/godot" target="_blank" rel="noreferrer">https://pd.qq.com/g/godot</a></li></ul><p>問題の報告や機能提案がある場合は、Konado のプロジェクト<a href="https://github.com/godothub/konado/issues" target="_blank" rel="noreferrer">リポジトリで Issue を作成</a>してください。</p><p>その他の質問は、<a href="mailto:konado@godothub.com" target="_blank" rel="noreferrer">konado@godothub.com</a> までメールでお問い合わせください。</p><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p><a href="https://www.cngal.org" target="_blank" rel="noreferrer"><img src="'+t+'" alt="CNGAL"></a></p>',22)])])}const b=o(s,[["render",n]]);export{g as __pageData,b as default};
